// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// SubmitClinic Submit a clinic; the caller becomes its clinic admin. Listed only after verification
	// (POST /v1/clinics)
	SubmitClinic(ctx context.Context, request SubmitClinicRequestObject) (SubmitClinicResponseObject, error)
	// ListBranches The branches of my clinic (main branch first; a clinic has at most 50, so one page)
	// (GET /v1/clinics/{clinicId}/branches)
	ListBranches(ctx context.Context, request ListBranchesRequestObject) (ListBranchesResponseObject, error)
	// CreateBranch Add a branch location to my clinic (each branch is located separately)
	// (POST /v1/clinics/{clinicId}/branches)
	CreateBranch(ctx context.Context, request CreateBranchRequestObject) (CreateBranchResponseObject, error)
	// UpdateBranch Change a branch of my clinic (address, pin, zone, name, on or off)
	// (PATCH /v1/clinics/{clinicId}/branches/{branchId})
	UpdateBranch(ctx context.Context, request UpdateBranchRequestObject) (UpdateBranchResponseObject, error)
	// CreatePractice Add a doctor's practice at my clinic
	// (POST /v1/clinics/{clinicId}/practices)
	CreatePractice(ctx context.Context, request CreatePracticeRequestObject) (CreatePracticeResponseObject, error)
	// ListMyPracticeInvitations My pending invitations (a clinic naming me lead doctor, or listing me at its practice)
	// (GET /v1/me/practice-invitations)
	ListMyPracticeInvitations(ctx context.Context, request ListMyPracticeInvitationsRequestObject) (ListMyPracticeInvitationsResponseObject, error)
	// AcceptPracticeInvitation Accept an invitation. Until then it never counts for listing
	// (POST /v1/me/practice-invitations/{invitationId}/accept)
	AcceptPracticeInvitation(ctx context.Context, request AcceptPracticeInvitationRequestObject) (AcceptPracticeInvitationResponseObject, error)
	// DeclinePracticeInvitation Decline an invitation
	// (POST /v1/me/practice-invitations/{invitationId}/decline)
	DeclinePracticeInvitation(ctx context.Context, request DeclinePracticeInvitationRequestObject) (DeclinePracticeInvitationResponseObject, error)
	// UpsertMyProfessional Create or change my doctor profile (listed only once I am Verified)
	// (PUT /v1/me/professional)
	UpsertMyProfessional(ctx context.Context, request UpsertMyProfessionalRequestObject) (UpsertMyProfessionalResponseObject, error)
	// SearchPractices Find listed practices near a point or a PIN code (location in the body, never stored)
	// (POST /v1/practices/search)
	SearchPractices(ctx context.Context, request SearchPracticesRequestObject) (SearchPracticesResponseObject, error)
	// GetPractice Public profile of a listed practice (unverified or unknown answers 404)
	// (GET /v1/practices/{practiceId})
	GetPractice(ctx context.Context, request GetPracticeRequestObject) (GetPracticeResponseObject, error)
	// UpdatePractice Change a practice (the doctor's own, or one at the caller's clinic)
	// (PATCH /v1/practices/{practiceId})
	UpdatePractice(ctx context.Context, request UpdatePracticeRequestObject) (UpdatePracticeResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

